"""Semantic version parsing, comparison, and range matching.

Versions follow Semantic Versioning 2.0.0: ``MAJOR.MINOR.PATCH``, then an
optional pre-release (``-`` followed by dot-separated identifiers) and an
optional build (``+`` followed by dot-separated identifiers). Identifiers
are non-empty and made of ASCII letters, digits, and hyphens. Numeric parts
(MAJOR, MINOR, PATCH, and all-digit pre-release identifiers) must not have
leading zeros. Anything else is invalid and raises ``ValueError``.

Precedence (``compare``) follows the SemVer 2.0.0 rules: compare MAJOR,
MINOR, and PATCH numerically; a version with a pre-release is lower than
the same version without one; pre-release identifiers are compared left to
right, all-digit ones numerically and the rest in ASCII order, with
all-digit identifiers lower than the rest, and a shorter list lower when
all its identifiers equal the start of a longer one. Build metadata is
ignored.

Ranges (``satisfies``) are one or more comparator sets joined by ``||``; a
version satisfies the range if it satisfies any set. A set is one or more
comparators separated by whitespace, all of which must hold. A comparator
is a full version optionally prefixed by an operator:

- ``=`` (or no operator), ``>``, ``>=``, ``<``, ``<=``: by precedence.
- ``^X.Y.Z``: at least ``X.Y.Z`` and below the next version that changes
  the leftmost non-zero part, i.e. ``^1.2.3`` is ``>=1.2.3 <2.0.0``,
  ``^0.2.3`` is ``>=0.2.3 <0.3.0``, and ``^0.0.3`` is ``>=0.0.3 <0.0.4``.
- ``~X.Y.Z``: at least ``X.Y.Z`` and below ``X.(Y+1).0``.

A version with a pre-release satisfies a set only if some comparator in
that set has a pre-release on the same MAJOR.MINOR.PATCH (so
``1.2.3-beta.2`` satisfies ``>=1.2.3-beta.1`` but not ``>=1.0.0``).
Invalid ranges raise ``ValueError``.
"""

from __future__ import annotations

import re
from dataclasses import dataclass

_IDENTIFIER = r"[0-9A-Za-z-]+"
_VERSION_RE = re.compile(
    r"(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)"
    r"(?:-(" + _IDENTIFIER + r"(?:\." + _IDENTIFIER + r")*))?"
    r"(?:\+(" + _IDENTIFIER + r"(?:\." + _IDENTIFIER + r")*))?"
)
_COMPARATOR_RE = re.compile(r"(<=|>=|<|>|=|\^|~)?(.+)")
_ALL_DIGITS_RE = re.compile(r"[0-9]+")
_IDENTIFIER_RE = re.compile(_IDENTIFIER)


@dataclass(frozen=True)
class Version:
    major: int
    minor: int
    patch: int
    prerelease: tuple[str, ...] = ()
    build: tuple[str, ...] = ()

    def __str__(self) -> str:
        """The version in canonical form, e.g. ``1.2.3-rc.1+build.5``."""
        text = f"{self.major}.{self.minor}.{self.patch}"
        if self.prerelease:
            text += "-" + ".".join(str(part) for part in self.prerelease)
        if self.build:
            text += "+" + ".".join(str(part) for part in self.build)
        return text


def _parse_identifiers(text: str, *, prerelease: bool) -> tuple[str, ...]:
    identifiers = text.split(".")
    for identifier in identifiers:
        if not _IDENTIFIER_RE.fullmatch(identifier):
            raise ValueError(f"invalid version identifier: {identifier!r}")
        if prerelease and _ALL_DIGITS_RE.fullmatch(identifier):
            if len(identifier) > 1 and identifier[0] == "0":
                raise ValueError(
                    f"numeric pre-release identifier has a leading zero: {identifier!r}"
                )
    return tuple(identifiers)


def parse(text: str) -> Version:
    """Parse a version string."""
    if not isinstance(text, str):
        raise ValueError(f"version must be a string, not {type(text).__name__}")
    match = _VERSION_RE.fullmatch(text)
    if match is None:
        raise ValueError(f"invalid version: {text!r}")
    major, minor, patch, prerelease, build = match.groups()
    return Version(
        int(major),
        int(minor),
        int(patch),
        _parse_identifiers(prerelease, prerelease=True) if prerelease else (),
        _parse_identifiers(build, prerelease=False) if build else (),
    )


def _as_version(value: str | Version) -> Version:
    if isinstance(value, Version):
        return value
    return parse(value)


def compare(a: str | Version, b: str | Version) -> int:
    """Return -1, 0, or 1 as ``a`` has lower, equal, or higher precedence."""
    left = _as_version(a)
    right = _as_version(b)

    for name in ("major", "minor", "patch"):
        left_part = getattr(left, name)
        right_part = getattr(right, name)
        if left_part != right_part:
            return -1 if left_part < right_part else 1

    if not left.prerelease and not right.prerelease:
        return 0
    if not left.prerelease:
        return 1
    if not right.prerelease:
        return -1

    for left_part, right_part in zip(left.prerelease, right.prerelease):
        left_numeric = _ALL_DIGITS_RE.fullmatch(left_part) is not None
        right_numeric = _ALL_DIGITS_RE.fullmatch(right_part) is not None
        if left_numeric and right_numeric:
            left_number = int(left_part)
            right_number = int(right_part)
            if left_number != right_number:
                return -1 if left_number < right_number else 1
        elif left_numeric:
            return -1
        elif right_numeric:
            return 1
        elif left_part != right_part:
            return -1 if left_part < right_part else 1

    if len(left.prerelease) == len(right.prerelease):
        return 0
    return -1 if len(left.prerelease) < len(right.prerelease) else 1


def _caret_upper(version: Version) -> Version:
    if version.major:
        return Version(version.major + 1, 0, 0)
    if version.minor:
        return Version(0, version.minor + 1, 0)
    return Version(0, 0, version.patch + 1)


def _parse_set(text: str) -> list[tuple[str, Version]]:
    comparators: list[tuple[str, Version]] = []
    for token in text.split():
        match = _COMPARATOR_RE.fullmatch(token)
        if match is None:
            raise ValueError(f"invalid comparator: {token!r}")
        operator, version_text = match.groups()
        operator = operator or "="
        comparators.append((operator, parse(version_text)))
    if not comparators:
        raise ValueError("empty comparator set")
    return comparators


def _matches(version: Version, operator: str, target: Version) -> bool:
    if operator == "^":
        return compare(version, target) >= 0 and compare(version, _caret_upper(target)) < 0
    if operator == "~":
        upper = Version(target.major, target.minor + 1, 0)
        return compare(version, target) >= 0 and compare(version, upper) < 0

    result = compare(version, target)
    if operator == "=":
        return result == 0
    if operator == ">":
        return result > 0
    if operator == ">=":
        return result >= 0
    if operator == "<":
        return result < 0
    if operator == "<=":
        return result <= 0
    raise ValueError(f"invalid comparator operator: {operator!r}")


def satisfies(version: str | Version, range_: str) -> bool:
    """Whether ``version`` is in ``range_``."""
    candidate = _as_version(version)
    if not isinstance(range_, str):
        raise ValueError(f"range must be a string, not {type(range_).__name__}")

    sets = range_.split("||")
    if not sets:
        raise ValueError("empty range")
    for set_text in sets:
        if not set_text.strip():
            raise ValueError(f"invalid range: {range_!r}")
        comparators = _parse_set(set_text)

        if candidate.prerelease:
            allowed = any(
                target.prerelease
                and (target.major, target.minor, target.patch)
                == (candidate.major, candidate.minor, candidate.patch)
                for _, target in comparators
            )
            if not allowed:
                continue

        if all(_matches(candidate, operator, target) for operator, target in comparators):
            return True
    return False

"""ISO 8601 durations.

A duration is ``P`` followed by date parts ``nY``, ``nM``, ``nW``, ``nD``
(in that order, each optional), then optionally ``T`` followed by time parts
``nH``, ``nM``, ``nS`` (in that order, each optional). Each ``n`` is a
non-negative integer, except that seconds may have a decimal fraction
(``PT1.5S``). At least one part must be present, and ``T`` must be followed
by at least one time part, so ``P``, ``PT``, ``P1H``, ``1D``, ``PT1.5M`` and
``P1D2Y`` are invalid. Parsing is case-sensitive; invalid input raises
``ValueError``.

``format`` writes the canonical form: parts in the order above, parts that
are zero left out, ``T`` only when a time part is present, and seconds
without a fraction when they are whole (``PT1S``, ``PT1.5S``). The zero
duration is ``PT0S``.

``add`` adds a duration to a datetime: first years and months, keeping the
day of the month but clamping it to the last day of the resulting month
(Jan 31 plus one month is Feb 28, or 29 in a leap year), then weeks, days,
hours, minutes, and seconds as exact elapsed time.
"""

from __future__ import annotations

import builtins
import calendar
import re
from dataclasses import dataclass
from datetime import datetime, timedelta
from decimal import Decimal

_DATE_RE = re.compile(
    r"(?:(?P<years>[0-9]+)Y)?"
    r"(?:(?P<months>[0-9]+)M)?"
    r"(?:(?P<weeks>[0-9]+)W)?"
    r"(?:(?P<days>[0-9]+)D)?"
)
_TIME_RE = re.compile(
    r"(?:(?P<hours>[0-9]+)H)?"
    r"(?:(?P<minutes>[0-9]+)M)?"
    r"(?:(?P<seconds>[0-9]+(?:\.[0-9]+)?)S)?"
)


@dataclass(frozen=True)
class Duration:
    years: int = 0
    months: int = 0
    weeks: int = 0
    days: int = 0
    hours: int = 0
    minutes: int = 0
    seconds: float = 0


def parse(text: str) -> Duration:
    """Parse an ISO 8601 duration."""
    if not isinstance(text, str) or not text.startswith("P"):
        raise ValueError(f"invalid duration: {text!r}")

    body = text[1:]
    if "T" in body:
        if body.count("T") != 1:
            raise ValueError(f"invalid duration: {text!r}")
        date_text, time_text = body.split("T")
        time_match = _TIME_RE.fullmatch(time_text)
        if time_match is None or not any(time_match.groups()):
            raise ValueError(f"invalid duration: {text!r}")
    else:
        date_text = body
        time_match = None

    date_match = _DATE_RE.fullmatch(date_text)
    if date_match is None or not any(date_match.groups()):
        raise ValueError(f"invalid duration: {text!r}")

    values = {key: int(value) for key, value in date_match.groupdict().items() if value}
    if time_match is not None:
        time_values = time_match.groupdict()
        for key in ("hours", "minutes"):
            if time_values[key]:
                values[key] = int(time_values[key])
        if time_values["seconds"]:
            values["seconds"] = float(time_values["seconds"])

    return Duration(**values)


def _format_seconds(seconds: float) -> str:
    if isinstance(seconds, int):
        return str(seconds)
    if seconds.is_integer():
        return str(int(seconds))
    text = repr(float(seconds))
    if "e" in text or "E" in text:
        text = builtins.format(Decimal(text), "f")
    if "." in text:
        text = text.rstrip("0").rstrip(".")
    return text


def format(duration: Duration) -> str:
    """Write ``duration`` in canonical ISO 8601 form."""
    date_parts = []
    for value, suffix in (
        (duration.years, "Y"),
        (duration.months, "M"),
        (duration.weeks, "W"),
        (duration.days, "D"),
    ):
        if value:
            date_parts.append(f"{value}{suffix}")

    time_parts = []
    for value, suffix in (
        (duration.hours, "H"),
        (duration.minutes, "M"),
    ):
        if value:
            time_parts.append(f"{value}{suffix}")
    if duration.seconds:
        time_parts.append(f"{_format_seconds(duration.seconds)}S")

    if not date_parts and not time_parts:
        return "PT0S"

    text = "P" + "".join(date_parts)
    if time_parts:
        text += "T" + "".join(time_parts)
    return text


def add(moment: datetime, duration: Duration) -> datetime:
    """``moment`` plus ``duration``."""
    total_months = moment.month - 1 + duration.years * 12 + duration.months
    year = moment.year + total_months // 12
    month = total_months % 12 + 1
    day = min(moment.day, calendar.monthrange(year, month)[1])
    moment = moment.replace(year=year, month=month, day=day)

    return moment + timedelta(
        weeks=duration.weeks,
        days=duration.days,
        hours=duration.hours,
        minutes=duration.minutes,
        seconds=duration.seconds,
    )

"""Find when a cron schedule next fires.

An expression has five whitespace-separated fields: minute (0-59), hour
(0-23), day of month (1-31), month (1-12), and day of week (0-7, where both
0 and 7 are Sunday). Each field is a comma-separated list of items, where
an item is:

- ``*``, every value in the field's range,
- a value ``N``,
- a range ``A-B`` (inclusive, with ``A <= B``),
- any of those followed by ``/S`` for every ``S``-th value starting at the
  first one (``*/15`` in the minute field is 0, 15, 30, 45; ``10-30/10`` is
  10, 20, 30; ``5/20`` is 5, 25, 45, i.e. from 5 to the end of the range).

Months may also be given by the names ``JAN``-``DEC`` and days of the week
by ``SUN``-``SAT``, in any case, including in ranges. A value outside its
field's range, a malformed item, or a field count other than five raises
``ValueError``.

As in Vixie cron, when both the day-of-month and day-of-week fields are
restricted (neither is exactly ``*``), a day matches if it matches either
one; otherwise it must match both.

Times are naive datetimes. ``next_run`` returns the earliest matching time
strictly after ``after``, with seconds and microseconds zero. If nothing
matches within the next five years (e.g. ``0 0 30 2 *``), it raises
``ValueError``.
"""

from __future__ import annotations

import calendar
import re
from datetime import datetime, timedelta

_MONTH_NAMES = {
    name: number
    for number, name in enumerate(
        ("JAN", "FEB", "MAR", "APR", "MAY", "JUN",
         "JUL", "AUG", "SEP", "OCT", "NOV", "DEC"),
        start=1,
    )
}
_DOW_NAMES = {
    name: number
    for number, name in enumerate(("SUN", "MON", "TUE", "WED", "THU", "FRI", "SAT"))
}
_NUMBER_RE = re.compile(r"[0-9]+")


def _resolve_value(text: str, names: dict[str, int], low: int, high: int) -> int:
    name = text.upper()
    if name in names:
        value = names[name]
    elif _NUMBER_RE.fullmatch(text):
        value = int(text)
    else:
        raise ValueError(f"invalid value: {text!r}")
    if not low <= value <= high:
        raise ValueError(f"value out of range: {text!r}")
    return value


def _parse_field(
    text: str, low: int, high: int, names: dict[str, int]
) -> set[int]:
    values: set[int] = set()
    for item in text.split(","):
        if not item:
            raise ValueError(f"malformed field item in {text!r}")

        base, separator, step_text = item.partition("/")
        if separator:
            if "/" in step_text or not _NUMBER_RE.fullmatch(step_text):
                raise ValueError(f"malformed step in {item!r}")
            step = int(step_text)
            if step <= 0:
                raise ValueError(f"step must be positive in {item!r}")
        else:
            step = 1

        if base == "*":
            start, end = low, high
        elif "-" in base:
            start_text, dash, end_text = base.partition("-")
            if not dash or "-" in end_text or not start_text or not end_text:
                raise ValueError(f"malformed range in {item!r}")
            start = _resolve_value(start_text, names, low, high)
            end = _resolve_value(end_text, names, low, high)
            if start > end:
                raise ValueError(f"reversed range in {item!r}")
        else:
            start = _resolve_value(base, names, low, high)
            end = high

        values.update(range(start, end + 1, step))
    return values


def _add_years(moment: datetime, years: int) -> datetime:
    year = moment.year + years
    day = min(moment.day, calendar.monthrange(year, moment.month)[1])
    return moment.replace(year=year, day=day)


def next_run(expression: str, after: datetime) -> datetime:
    """The first time after ``after`` that ``expression`` fires."""
    fields = expression.split()
    if len(fields) != 5:
        raise ValueError("cron expression must have five fields")

    minute_text, hour_text, dom_text, month_text, dow_text = fields
    minutes = _parse_field(minute_text, 0, 59, {})
    hours = _parse_field(hour_text, 0, 23, {})
    days = _parse_field(dom_text, 1, 31, {})
    months = _parse_field(month_text, 1, 12, _MONTH_NAMES)
    weekdays = {
        value % 7 for value in _parse_field(dow_text, 0, 7, _DOW_NAMES)
    }

    dom_restricted = dom_text != "*"
    dow_restricted = dow_text != "*"

    start = after.replace(second=0, microsecond=0) + timedelta(minutes=1)
    limit = _add_years(after, 5)

    sorted_hours = sorted(hours)
    sorted_minutes = sorted(minutes)
    day = start.date()
    last_day = limit.date()

    while day <= last_day:
        if day.month in months:
            cron_weekday = (day.weekday() + 1) % 7
            dom_match = day.day in days
            dow_match = cron_weekday in weekdays
            if dom_restricted and dow_restricted:
                day_match = dom_match or dow_match
            else:
                day_match = dom_match and dow_match

            if day_match:
                for hour in sorted_hours:
                    if day == start.date() and hour < start.hour:
                        continue
                    for minute in sorted_minutes:
                        if (
                            day == start.date()
                            and hour == start.hour
                            and minute < start.minute
                        ):
                            continue
                        candidate = start.replace(
                            year=day.year,
                            month=day.month,
                            day=day.day,
                            hour=hour,
                            minute=minute,
                        )
                        if candidate > limit:
                            raise ValueError(
                                f"cron expression {expression!r} does not fire "
                                "within five years"
                            )
                        return candidate
        day += timedelta(days=1)

    raise ValueError(
        f"cron expression {expression!r} does not fire within five years"
    )

"""Write and read Markdown (GitHub-flavored) pipe tables.

``format_table`` writes a header line, a delimiter line, and one line per
row, separated by ``\\n`` with no trailing newline. Every line is ``| ``,
then the column cells joined by `` | ``, then `` |``.

Cell text is ``str(value)``, or empty for ``None``, with each ``|``
escaped as ``\\|``. A row shorter than the header is padded with empty
cells; a longer one raises ``ValueError``. Each column is as wide as its
longest cell text (after escaping, and including the header), and at
least 3.

Cells are padded with spaces to the column width according to the
column's alignment: ``"left"`` or ``None`` pads on the right, ``"right"``
pads on the left, and ``"center"`` pads both sides equally, with any odd
space on the right. ``align`` gives one alignment per column (default all
``None``); any other value, or a list of the wrong length, raises
``ValueError``.

Delimiter cells are dashes filling the column width, with a colon replacing
the first dash for ``"left"``, the last for ``"right"``, and both for
``"center"`` (``:--``, ``--:``, ``:-:`` at width 3).

``parse_table`` reads such a table back, tolerating any padding and missing
leading or trailing pipes: it returns the header and the rows as lists of
stripped strings with ``\\|`` unescaped, and the alignment of each column
from the delimiter line (``None`` for plain dashes). Each delimiter cell
must be one or more dashes with an optional colon at either end. Text that
isn't a table (fewer than two lines, a bad delimiter line, or a delimiter
line or row with a different number of cells than the header) raises
``ValueError``.
"""

from __future__ import annotations

_ALIGNMENTS = (None, "left", "right", "center")
_DELIMITER_RE = __import__("re").compile(r":?-+:?")


def _cell_text(value: object) -> str:
    if value is None:
        return ""
    return str(value).replace("|", "\\|")


def _pad(text: str, width: int, alignment: str | None) -> str:
    padding = width - len(text)
    if alignment == "right":
        return " " * padding + text
    if alignment == "center":
        left = padding // 2
        return " " * left + text + " " * (padding - left)
    return text + " " * padding


def _delimiter(width: int, alignment: str | None) -> str:
    if alignment == "left":
        return ":" + "-" * (width - 1)
    if alignment == "right":
        return "-" * (width - 1) + ":"
    if alignment == "center":
        return ":" + "-" * (width - 2) + ":"
    return "-" * width


def format_table(
    header: list, rows: list[list], align: list[str | None] | None = None
) -> str:
    """Write a Markdown table."""
    header_cells = [_cell_text(value) for value in header]
    column_count = len(header_cells)

    if align is None:
        alignments = [None] * column_count
    else:
        if not isinstance(align, list):
            raise ValueError("align must be a list")
        if len(align) != column_count:
            raise ValueError("align must have one entry per column")
        for alignment in align:
            if alignment not in _ALIGNMENTS:
                raise ValueError(f"invalid alignment: {alignment!r}")
        alignments = list(align)

    row_cells: list[list[str]] = []
    for row in rows:
        if len(row) > column_count:
            raise ValueError("row has more cells than the header")
        cells = [_cell_text(value) for value in row]
        cells.extend("" for _ in range(column_count - len(cells)))
        row_cells.append(cells)

    widths = [3] * column_count
    for index, text in enumerate(header_cells):
        widths[index] = max(widths[index], len(text))
    for cells in row_cells:
        for index, text in enumerate(cells):
            widths[index] = max(widths[index], len(text))

    def render(cells: list[str]) -> str:
        padded = [
            _pad(text, widths[index], alignments[index])
            for index, text in enumerate(cells)
        ]
        return "| " + " | ".join(padded) + " |"

    lines = [render(header_cells)]
    lines.append(
        "| "
        + " | ".join(
            _delimiter(widths[index], alignments[index])
            for index in range(column_count)
        )
        + " |"
    )
    lines.extend(render(cells) for cells in row_cells)
    return "\n".join(lines)


def _split_cells(line: str) -> list[str]:
    line = line.strip()
    cells: list[str] = []
    buffer: list[str] = []
    ended_with_pipe = False
    index = 0

    while index < len(line):
        char = line[index]
        if char == "\\" and index + 1 < len(line) and line[index + 1] == "|":
            buffer.append("|")
            index += 2
            ended_with_pipe = False
        elif char == "|":
            cells.append("".join(buffer))
            buffer = []
            index += 1
            ended_with_pipe = True
        else:
            buffer.append(char)
            index += 1
            ended_with_pipe = False
    cells.append("".join(buffer))
    if ended_with_pipe:
        cells.pop()

    if line.startswith("|") and cells:
        cells.pop(0)

    return [cell.strip() for cell in cells]


def parse_table(
    text: str,
) -> tuple[list[str], list[list[str]], list[str | None]]:
    """Read a Markdown table into its header, rows, and alignments."""
    lines = text.splitlines()
    if len(lines) < 2:
        raise ValueError("not a Markdown table")

    header = _split_cells(lines[0])
    delimiter = _split_cells(lines[1])
    if len(delimiter) != len(header):
        raise ValueError("delimiter line has a different number of cells")

    alignments: list[str | None] = []
    for cell in delimiter:
        if _DELIMITER_RE.fullmatch(cell) is None:
            raise ValueError(f"invalid delimiter cell: {cell!r}")
        left = cell.startswith(":")
        right = cell.endswith(":")
        if left and right:
            alignments.append("center")
        elif left:
            alignments.append("left")
        elif right:
            alignments.append("right")
        else:
            alignments.append(None)

    rows: list[list[str]] = []
    for line in lines[2:]:
        cells = _split_cells(line)
        if len(cells) != len(header):
            raise ValueError("row has a different number of cells")
        rows.append(cells)

    return header, rows, alignments

